import { Component, TemplateRef, computed, inject, signal, viewChild } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { IconEye, IconEdit, IconTrash, IconPlus, IconArrowsSort } from '@tabler/icons-angular';
import { TablerIconComponent } from '@tabler/icons-angular';
import { TranslateModule, TranslateService } from '@ngx-translate/core';
import {
  HrmGrid, HrmGridColumn, HrmCard, HrmTableToolbar, HrmInput, HrmButton,
  HrmUserCell, HrmTextCell, HrmTagsCell, HrmTagItem,
  HrmProgressCell, HrmStatusCell, HrmActionCell, HrmActionItem,
  HrmSortConfig, HrmSortColumn, HrmGridSort, HrmDataToolbar,
} from 'hrm-ui';
import { SgDoc } from '../../../doc/sg-doc';
import { SgUse, SgDo, SgDont, SgExample } from '../../../doc/sg-blocks';

/** Doc page · Table (Table & List) — Ô giàu bằng Table Cells / Sortable / Selection / Striped / In Card.
 *  Kiểu bảng chuẩn: line NGANG từng dòng, không line dọc chia cột. Song ngữ qua i18n docs.enterpriseGrid.*. */
@Component({
  selector: 'sg-doc-grid-ent',
  imports: [
    FormsModule, TablerIconComponent, TranslateModule,
    HrmGrid, HrmCard, HrmTableToolbar, HrmInput, HrmButton, HrmSortConfig, HrmDataToolbar,
    HrmUserCell, HrmTextCell, HrmTagsCell, HrmProgressCell, HrmStatusCell, HrmActionCell,
    SgDoc, SgUse, SgDo, SgDont, SgExample,
  ],
  template: `
    <sg-doc category="Table & List" [title]="'docs.enterpriseGrid.title' | translate" [desc]="'docs.enterpriseGrid.desc' | translate">

      <div sgOverview>
        <div style="width:100%">
          <hrm-grid [columns]="richCols()" [data]="people" [showPagination]="false" />
        </div>
      </div>

      <div sgUsage>
        <sg-use [purpose]="'docs.enterpriseGrid.purpose' | translate" [when]="when"
          [behavior]="'docs.enterpriseGrid.behavior' | translate"
          [avoid]="'docs.enterpriseGrid.avoid' | translate" />
      </div>

      <div sgBest>
        <sg-do>{{ 'docs.enterpriseGrid.do1' | translate }}</sg-do>
        <sg-do>{{ 'docs.enterpriseGrid.do2' | translate }}</sg-do>
        <sg-dont>{{ 'docs.enterpriseGrid.dont1' | translate }}</sg-dont>
      </div>

      <div sgExamples>
        <sg-example [title]="'docs.enterpriseGrid.exRecordT' | translate"
          [desc]="'docs.enterpriseGrid.exRecordD' | translate">
          <div style="width:100%;max-width:560px">
            <hrm-grid variant="record" [columns]="recordCols()" [record]="people[0]" />
          </div>
        </sg-example>

        <sg-example [title]="'docs.enterpriseGrid.exToolbarT' | translate"
          [desc]="'docs.enterpriseGrid.exToolbarD' | translate">
          <div style="width:100%">
            <hrm-table-toolbar [title]="'docs.enterpriseGrid.toolbarTitle' | translate" [count]="people.length" [countLabel]="'docs.enterpriseGrid.countLabel' | translate" [divided]="true">
              <hrm-input [(ngModel)]="kw" [placeholder]="'docs.enterpriseGrid.searchPh' | translate" style="width:260px" />
              <hrm-button variant="primary" tbActions><tabler-icon [icon]="plus" [size]="16" /> {{ 'docs.enterpriseGrid.addEmployee' | translate }}</hrm-button>
            </hrm-table-toolbar>
            <hrm-grid [columns]="selCols()" [data]="people" [showPagination]="false" />
          </div>
        </sg-example>

        <sg-example [title]="'docs.enterpriseGrid.exRichT' | translate"
          [desc]="'docs.enterpriseGrid.exRichD' | translate">
          <div style="width:100%">
            <hrm-grid [columns]="richCols()" [data]="people" [showPagination]="false" />
          </div>
        </sg-example>

        <sg-example [title]="'docs.enterpriseGrid.exSortT' | translate"
          [desc]="'docs.enterpriseGrid.exSortD' | translate">
          <!-- Toolbar DÍNH bảng trong 1 panel viền chung (toolbar gạch dưới, bảng phẳng) -->
          <div class="tbx-panel" style="width:100%">
            <hrm-data-toolbar class="tbx-bar"
              [count]="filteredPeople().length" countLabel="nhân viên"
              [(search)]="tbSearch" searchPlaceholder="Tìm theo tên hoặc email…"
              [filterable]="true" (filterClick)="onTbFilter()"
              [exportable]="true" (exportClick)="onTbExport()"
              [sortColumns]="sortableColumns()" [(sortLevels)]="demoSort"
              [columns]="sortableColumns()" [(hiddenKeys)]="tbHidden" />
            <hrm-grid [columns]="sortRichCols()" [data]="filteredPeople()" [showPagination]="false"
              [(sortLevels)]="demoSort" [(hiddenKeys)]="tbHidden" />
          </div>
        </sg-example>

        <sg-example [title]="'docs.enterpriseGrid.exSelectT' | translate"
          [desc]="'docs.enterpriseGrid.exSelectD' | translate">
          <div style="width:100%">
            <p style="font-size: var(--fs-13);color:var(--text-sub);margin:0 0 8px">{{ 'docs.enterpriseGrid.selectedPre' | translate }} <b>{{ picked().length }}</b> {{ 'docs.enterpriseGrid.selectedPost' | translate }}</p>
            <hrm-grid [columns]="selCols()" [data]="people" [showPagination]="false"
              [selectable]="true" rowKey="id" [(selectedKeys)]="pickedModel" />
          </div>
        </sg-example>

        <sg-example [title]="'docs.enterpriseGrid.exStripedT' | translate"
          [desc]="'docs.enterpriseGrid.exStripedD' | translate">
          <div style="width:100%">
            <hrm-grid [columns]="stripedCols()" [data]="people" [striped]="true" [showPagination]="false" />
          </div>
        </sg-example>

        <sg-example [title]="'docs.enterpriseGrid.exDividersT' | translate"
          [desc]="'docs.enterpriseGrid.exDividersD' | translate">
          <div style="width:100%;display:flex;flex-direction:column;gap:16px">
            <div>
              <p class="dv-cap">{{ 'docs.enterpriseGrid.capRows' | translate }}</p>
              <hrm-grid [columns]="plainCols()" [data]="peopleShort" [showPagination]="false" />
            </div>
            <div>
              <p class="dv-cap">{{ 'docs.enterpriseGrid.capColumns' | translate }}</p>
              <hrm-grid dividers="columns" [columns]="plainCols()" [data]="peopleShort" [showPagination]="false" />
            </div>
            <div>
              <p class="dv-cap">{{ 'docs.enterpriseGrid.capGrid' | translate }}</p>
              <hrm-grid dividers="grid" [columns]="plainCols()" [data]="peopleShort" [showPagination]="false" />
            </div>
            <div>
              <p class="dv-cap">{{ 'docs.enterpriseGrid.capNone' | translate }}</p>
              <hrm-grid dividers="none" [columns]="plainCols()" [data]="peopleShort" [showPagination]="false" />
            </div>
          </div>
        </sg-example>

        <sg-example [title]="'docs.enterpriseGrid.exTruncT' | translate"
          [desc]="'docs.enterpriseGrid.exTruncD' | translate">
          <div style="width:340px">
            <hrm-grid textOverflow="truncate" [columns]="truncCols()" [data]="people" [showPagination]="false" />
          </div>
        </sg-example>

        <sg-example [title]="'docs.enterpriseGrid.exInCardT' | translate"
          [desc]="'docs.enterpriseGrid.exInCardD' | translate">
          <div style="width:100%">
            <hrm-card [title]="'docs.enterpriseGrid.cardTitle' | translate" [flush]="true">
              <hrm-grid [columns]="inCardCols()" [data]="people" [showPagination]="false" />
            </hrm-card>
          </div>
        </sg-example>
      </div>

    </sg-doc>

    <!-- Ô giàu — cắm thẳng thành phần Table Cells -->
    <!-- Bảng mặc định: avatar + tên + sub, KHÔNG chấm hiện diện (status là opt-in cho màn chấm công). -->
    <ng-template #userCell let-r>
      <hrm-user-cell [name]="$any(r.name)" [sub]="$any(r.email)" [colorful]="true" [avatarSize]="36" />
    </ng-template>
    <ng-template #roleCell let-r>
      <hrm-text-cell [primary]="$any(r.role) | translate" [secondary]="$any(r.tenure) | translate" />
    </ng-template>
    <ng-template #skillCell let-r>
      <hrm-tags-cell [tags]="skillsOf($any(r))" [max]="2" />
    </ng-template>
    <ng-template #kpiCell let-r>
      <hrm-progress-cell [value]="$any(r.kpi)" [color]="kpiColor($any(r.kpi))" />
    </ng-template>
    <!-- badge (tint + chữ đậm + chấm): trạng thái quy trình nổi bật mà không nhầm button. -->
    <ng-template #statusCell let-r>
      <hrm-status-cell [status]="r.status === 'active' ? 'success' : 'error'"
        [label]="(r.status === 'active' ? 'docs.enterpriseGrid.statusActive' : 'docs.enterpriseGrid.statusAbsent') | translate" variant="badge" [dot]="true" />
    </ng-template>
    <ng-template #actionCell>
      <hrm-action-cell [actions]="rowActions" [moreLabel]="'docs.enterpriseGrid.moreLabel' | translate" />
    </ng-template>
  `,
  styles: [`
    .dv-cap { margin: 0 0 6px; font-size: var(--fs-12); font-weight: 600; color: var(--text-sub); text-transform: uppercase; letter-spacing: .03em; }
    /* Toolbar DÍNH bảng: 1 panel viền, toolbar gạch dưới, bảng phẳng bên trong. */
    .tbx-panel { border: 1px solid var(--border-sub); border-radius: var(--radius-lg); overflow: hidden; }
    .tbx-panel .tbx-bar { display: block; padding: 8px 12px; border-bottom: 1px solid var(--border-sub); }
    .tbx-panel ::ng-deep .ant-table { border: 0; border-radius: 0; background: transparent; }
  `],
})
export class SgDocGridEnt {
  private readonly t = inject(TranslateService);
  /** Signal đổi theo ngôn ngữ hiện tại → cho các computed cột tự dịch lại tiêu đề khi chuyển VI/EN. */
  private readonly lang = signal(this.t.currentLang);
  constructor() {
    this.t.onLangChange.subscribe((e) => this.lang.set(e.lang));
  }
  protected readonly plus = IconPlus;
  protected kw = '';
  protected get rowActions(): HrmActionItem[] {
    return [
      { key: 'view', icon: IconEye, label: this.t.instant('docs.enterpriseGrid.actView') },
      { key: 'edit', icon: IconEdit, label: this.t.instant('docs.enterpriseGrid.actEdit') },
      { key: 'delete', icon: IconTrash, label: this.t.instant('docs.enterpriseGrid.actDelete'), danger: true },
    ];
  }

  /** Cột chữ thuần cho demo density/dividers. */
  protected readonly plainCols = computed<HrmGridColumn[]>(() => (this.lang(), [
    { key: 'name', title: this.t.instant('docs.enterpriseGrid.colEmployee') },
    { key: 'email', title: this.t.instant('docs.enterpriseGrid.colEmail') },
    { key: 'role', title: this.t.instant('docs.enterpriseGrid.colRole') },
    { key: 'tenure', title: this.t.instant('docs.enterpriseGrid.colTenure') },
  ]));
  /** Cột có width cho demo truncate (bảng hẹp 420px → email dài bị cắt "…"). */
  protected readonly truncCols = computed<HrmGridColumn[]>(() => (this.lang(), [
    { key: 'name', title: this.t.instant('docs.enterpriseGrid.colEmployee'), width: '130px' },
    { key: 'email', title: this.t.instant('docs.enterpriseGrid.colEmail') },
    { key: 'role', title: this.t.instant('docs.enterpriseGrid.colRole'), width: '100px' },
  ]));

  /** Dữ liệu ô giàu — role/tenure/skill là KEY i18n; render qua translate ở cell. Tên/email giữ literal. */
  protected readonly people: Record<string, unknown>[] = [
    { id: 1, name: 'Nguyễn Văn A', email: 'a.nguyen@vnr.vn', role: 'docs.enterpriseGrid.roleManager', tenure: 'docs.enterpriseGrid.tenure1', kpi: 92, status: 'active',
      skills: [{ label: 'docs.enterpriseGrid.skillManagement', color: 'blue' }, { label: 'docs.enterpriseGrid.skillRecruit', color: 'green' }, { label: 'docs.enterpriseGrid.skillTraining', color: 'teal' }] as HrmTagItem[] },
    { id: 2, name: 'Trần Thị B', email: 'b.tran@vnr.vn', role: 'docs.enterpriseGrid.roleSpecialist', tenure: 'docs.enterpriseGrid.tenure2', kpi: 68, status: 'active',
      skills: [{ label: 'Excel', color: 'green' }, { label: 'docs.enterpriseGrid.skillReport', color: 'purple' }] as HrmTagItem[] },
    { id: 3, name: 'Lê Văn C', email: 'c.le@vnr.vn', role: 'docs.enterpriseGrid.roleIntern', tenure: 'docs.enterpriseGrid.tenure3', kpi: 45, status: 'absent',
      skills: [{ label: 'Angular', color: 'blue' }, { label: 'Figma', color: 'pink' }] as HrmTagItem[] },
    { id: 4, name: 'Phạm Thu D', email: 'd.pham@vnr.vn', role: 'docs.enterpriseGrid.roleLead', tenure: 'docs.enterpriseGrid.tenure4', kpi: 81, status: 'active',
      skills: [{ label: 'docs.enterpriseGrid.skillPlanning', color: 'orange' }, { label: 'docs.enterpriseGrid.skillBudget', color: 'cyan' }] as HrmTagItem[] },
    { id: 5, name: 'Đỗ Minh E', email: 'e.do@vnr.vn', role: 'docs.enterpriseGrid.roleStaff', tenure: 'docs.enterpriseGrid.tenure5', kpi: 74, status: 'active',
      skills: [{ label: 'docs.enterpriseGrid.skillTimekeeping', color: 'blue' }, { label: 'docs.enterpriseGrid.skillRecords', color: 'purple' }] as HrmTagItem[] },
    { id: 6, name: 'Vũ Hải F', email: 'f.vu@vnr.vn', role: 'docs.enterpriseGrid.roleLead', tenure: 'docs.enterpriseGrid.tenure6', kpi: 58, status: 'absent',
      skills: [{ label: 'docs.enterpriseGrid.skillExternal', color: 'teal' }, { label: 'docs.enterpriseGrid.skillContract', color: 'pink' }] as HrmTagItem[] },
  ];

  /** Nhãn kỹ năng: key domain → dịch qua translate; proper noun (Angular, Excel, Figma) giữ literal. */
  protected skillsOf(r: Record<string, unknown>): HrmTagItem[] {
    return (r['skills'] as HrmTagItem[]).map((s) => ({ ...s, label: this.t.instant(s.label) }));
  }

  /** 3 dòng đầu — cho các demo xếp chồng đỡ dài. */
  protected readonly peopleShort = this.people.slice(0, 3);

  private readonly userCell = viewChild<TemplateRef<any>>('userCell');
  private readonly roleCell = viewChild<TemplateRef<any>>('roleCell');
  private readonly skillCell = viewChild<TemplateRef<any>>('skillCell');
  private readonly kpiCell = viewChild<TemplateRef<any>>('kpiCell');
  private readonly statusCell = viewChild<TemplateRef<any>>('statusCell');
  private readonly actionCell = viewChild<TemplateRef<any>>('actionCell');

  protected readonly richCols = computed<HrmGridColumn[]>(() => (this.lang(), [
    { key: 'name', title: this.t.instant('docs.enterpriseGrid.colEmployee'), cell: this.userCell() },
    { key: 'role', title: this.t.instant('docs.enterpriseGrid.colRole'), cell: this.roleCell() },
    { key: 'skills', title: this.t.instant('docs.enterpriseGrid.colSkills'), cell: this.skillCell() },
    { key: 'kpi', title: this.t.instant('docs.enterpriseGrid.colKpi'), width: '180px', cell: this.kpiCell() },
    { key: 'status', title: this.t.instant('docs.enterpriseGrid.colStatus'), cell: this.statusCell() },
    { key: 'act', title: '', align: 'right', width: '96px', cell: this.actionCell() },
  ]));

  /** Sắp xếp: tên (chuỗi) + KPI (số) sortable — sort chạy trên giá trị thô, ô vẫn render rich. */
  protected readonly sortRichCols = computed<HrmGridColumn[]>(() => (this.lang(), [
    { key: 'name', title: this.t.instant('docs.enterpriseGrid.colEmployee'), sortable: true, cell: this.userCell() },
    { key: 'role', title: this.t.instant('docs.enterpriseGrid.colRole'), cell: this.roleCell() },
    { key: 'kpi', title: this.t.instant('docs.enterpriseGrid.colKpi'), width: '180px', sortable: true, cell: this.kpiCell() },
    { key: 'status', title: this.t.instant('docs.enterpriseGrid.colStatus'), cell: this.statusCell() },
  ]));

  protected readonly selCols = computed<HrmGridColumn[]>(() => (this.lang(), [
    { key: 'name', title: this.t.instant('docs.enterpriseGrid.colEmployee'), cell: this.userCell() },
    { key: 'role', title: this.t.instant('docs.enterpriseGrid.colRole'), cell: this.roleCell() },
    { key: 'status', title: this.t.instant('docs.enterpriseGrid.colStatus'), cell: this.statusCell() },
  ]));

  /** Demo TOOLBAR "chế độ dữ liệu": search lọc data + sort đa cấp + ẩn/hiện cột — nối chung state với grid. */
  protected readonly sortIcon = IconArrowsSort;
  protected readonly demoSort = signal<HrmGridSort[]>([]);
  protected readonly tbSearch = signal('');
  protected readonly tbHidden = signal<string[]>([]);
  protected readonly sortableColumns = computed<HrmSortColumn[]>(() => (this.lang(), [
    { key: 'name', title: this.t.instant('docs.enterpriseGrid.colEmployee') },
    { key: 'role', title: this.t.instant('docs.enterpriseGrid.colRole') },
    { key: 'kpi', title: this.t.instant('docs.enterpriseGrid.colKpi') },
    { key: 'status', title: this.t.instant('docs.enterpriseGrid.colStatus') },
  ]));
  /** Consumer TỰ lọc theo search (toolbar chỉ phát searchChange / two-way search). */
  protected readonly filteredPeople = computed<Record<string, unknown>[]>(() => {
    const q = this.tbSearch().trim().toLowerCase();
    if (!q) return this.people;
    return this.people.filter((p) =>
      String(p['name'] ?? '').toLowerCase().includes(q) || String(p['email'] ?? '').toLowerCase().includes(q));
  });
  protected onTbFilter(): void { /* demo: consumer mở panel lọc riêng */ }
  protected onTbExport(): void { /* demo: consumer xuất dữ liệu */ }

  protected readonly stripedCols = computed<HrmGridColumn[]>(() => (this.lang(), [
    { key: 'name', title: this.t.instant('docs.enterpriseGrid.colEmployee'), cell: this.userCell() },
    { key: 'skills', title: this.t.instant('docs.enterpriseGrid.colSkills'), cell: this.skillCell() },
    { key: 'kpi', title: this.t.instant('docs.enterpriseGrid.colKpi'), width: '180px', cell: this.kpiCell() },
    { key: 'status', title: this.t.instant('docs.enterpriseGrid.colStatus'), cell: this.statusCell() },
  ]));

  /** Bản ghi đơn — mỗi cột 1 dòng nhãn|giá trị, tái dùng Table Cells. */
  protected readonly recordCols = computed<HrmGridColumn[]>(() => (this.lang(), [
    { key: 'name', title: this.t.instant('docs.enterpriseGrid.colEmployee'), cell: this.userCell() },
    { key: 'role', title: this.t.instant('docs.enterpriseGrid.colRole'), cell: this.roleCell() },
    { key: 'skills', title: this.t.instant('docs.enterpriseGrid.colSkills'), cell: this.skillCell() },
    { key: 'kpi', title: this.t.instant('docs.enterpriseGrid.colKpi'), cell: this.kpiCell() },
    { key: 'status', title: this.t.instant('docs.enterpriseGrid.colStatus'), cell: this.statusCell() },
  ]));

  protected readonly inCardCols = computed<HrmGridColumn[]>(() => (this.lang(), [
    { key: 'name', title: this.t.instant('docs.enterpriseGrid.colEmployee'), cell: this.userCell() },
    { key: 'role', title: this.t.instant('docs.enterpriseGrid.colRole'), cell: this.roleCell() },
    { key: 'act', title: '', align: 'right', width: '96px', cell: this.actionCell() },
  ]));

  protected kpiColor(v: number): 'green' | 'amber' | 'red' {
    return v >= 80 ? 'green' : v >= 60 ? 'amber' : 'red';
  }

  protected readonly picked = signal<unknown[]>([1]);
  protected get pickedModel() { return this.picked(); }
  protected set pickedModel(v: unknown[]) { this.picked.set(v); }

  protected readonly when = ['docs.enterpriseGrid.when1', 'docs.enterpriseGrid.when2'];
}
